#include "domain/exterior_browse.hpp"
#include "engine/native_population_registry.hpp"
#include "domain/resource_presentation.hpp"
#include <iostream>
using namespace stalthos;using namespace stalthos::fauna;
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
int main(){try{std::vector<HabitatSite> sites{{{0,0,24},true,true,{1}},{{12,0,24},true,true,{0}}};Population original(42,1001,sites,8,{1});auto before=original.snapshot();auto habitat=exteriorHabitat(sites,[](double,double){return 0.;},[](double,double){return false;});auto expanded=withExteriorBrowse(original,habitat,{1});auto after=expanded.snapshot();check(after.actors.size()==12,"four residents retained");for(std::size_t i=0;i<8;++i){auto a=before.actors[i],b=after.actors[i];check(a.id==b.id&&a.hunger==b.hunger&&a.thirst==b.thirst&&a.target==b.target&&a.position.x==b.position.x&&a.position.z==b.position.z&&a.activity==b.activity,"original eight unchanged");}
 const auto site=habitat.residents.back();check(habitat.sites[site].browse&&after.actors.back().activity==Activity::Browse,"visible resource site authored");std::uint64_t next=1;ResourceLedgerDto ledger{{{100,ResourceKind::Creek,10,0},{200,ResourceKind::Shrub,10,0},{208,ResourceKind::Shrub,1,0}}, {}};std::vector<RegionalResourceAnchor> anchors{{0,100,sites[0].position},{0,200,sites[0].position},{1,100,sites[1].position},{1,200,sites[1].position},{site,208,habitat.sites[site].position}};engine::NativePopulationRegistry host(expanded,ledger,{},anchors,next);host.advance({1,1},true);auto dto=host.ledger().resources.back();check(dto.id==208&&dto.consumedQuantity>0,"resident consumes patch");const auto npc=dto.consumedQuantity;const auto session=next++;check(host.consume(session,208,.5),"hero consumes same patch");check(!host.consume(session,208,.5),"hero replay idempotent");dto=host.ledger().resources.back();check(std::abs(dto.consumedQuantity-npc-.5)<1e-12,"shared exact quantity");auto visual=ShrubPresentation::evaluate(dto);check(visual.valid&&visual.foliageFraction<.5&&visual.woodyStemVisible,"finite foliage response preserves structure");check(host.snapshot().actors.back().hunger<.55,"NPC relief only with contact");std::cout<<"EXTERIOR_BROWSE_OK original8 shared hero/NPC ledger replay foliage\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
